+		}
+		iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
+		jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
+		if currentHost == "" && iHome != jHome {
