+func newConfigureChanges(before, after map[string]string) []string {
+	paths := make([]string, 0, len(after))
+	for path := range after {
+		if _, existed := before[path]; !existed {
+			paths = append(paths, path)
+		}
+	}
+	sort.Strings(paths)
+	return paths
+}
