1	package agent
2	
3	import (
4		"context"
5		"fmt"
6		"path/filepath"
7		"runtime"
8		"slices"
9		"strings"
10		"sync"
11	
12		"github.com/entireio/cli/cmd/entire/cli/agent/types"
13	)
14	
15	var (
16		registryMu sync.RWMutex
17		registry   = make(map[types.AgentName]Factory)
18	)
19	
20	// Factory creates a new agent instance
21	type Factory func() Agent
22	
23	// Register adds an agent factory to the registry.
24	// Called from init() in each agent implementation.
25	func Register(name types.AgentName, factory Factory) {
26		registryMu.Lock()
27		defer registryMu.Unlock()
28		registry[name] = factory
29	}
30	
31	// Get retrieves an agent by name.
32	//
33	
34	func Get(name types.AgentName) (Agent, error) {
35		registryMu.RLock()
36		defer registryMu.RUnlock()
37	
38		factory, ok := registry[name]
39		if !ok {
40			return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, List())
41		}
42		return factory(), nil
43	}
44	
45	// List returns all registered agent names in sorted order.
46	func List() []types.AgentName {
47		registryMu.RLock()
48		defer registryMu.RUnlock()
49	
50		names := make([]types.AgentName, 0, len(registry))
51		for name := range registry {
52			names = append(names, name)
53		}
54		slices.Sort(names)
55		return names
56	}
57	
58	// StringList returns user-facing agent names, excluding test-only agents.
59	func StringList() []string {
60		registryMu.RLock()
61		defer registryMu.RUnlock()
62	
63		names := make([]string, 0, len(registry))
64		for name, factory := range registry {
65			if to, ok := factory().(TestOnly); ok && to.IsTestOnly() {
66				continue
67			}
68			names = append(names, string(name))
69		}
70		slices.Sort(names)
71		return names
72	}
73	
74	// DetectAll returns all agents whose DetectPresence reports true.
75	// Agents are checked in sorted name order (via List()) for deterministic results.
76	// Returns an empty slice when no agent is detected.
77	func DetectAll(ctx context.Context) []Agent {
78		names := List() // sorted, lock-safe
79	
80		var detected []Agent
81		for _, name := range names {
82			ag, err := Get(name)
83			if err != nil {
84				continue
85			}
86			if present, err := ag.DetectPresence(ctx); err == nil && present {
87				detected = append(detected, ag)
88			}
89		}
90		return detected
91	}
92	
93	// AgentForTranscriptPath returns the registered agent whose session directory
94	// for repoPath contains the given transcript path. Used to disambiguate which
95	// agent owns a session when multiple agents' hooks fire for the same session
96	// ID — a Cursor transcript path uniquely identifies a Cursor session even
97	// when Claude Code's hook is the one firing.
98	//
99	// Returns (nil, false) if transcriptPath is empty, no agent claims it, or any
100	// registry lookup fails. Match is by directory prefix (with a separator) so
101	// "/x/.claude/projects/abc.jsonl" doesn't accidentally match an agent rooted
102	// at "/x/.claude/projects/ab".
103	//
104	//nolint:revive // AgentForTranscriptPath: stutter is intentional for package callers (agent.AgentForTranscriptPath reads naturally)
105	func AgentForTranscriptPath(transcriptPath, repoPath string) (Agent, bool) {
106		if transcriptPath == "" {
107			return nil, false
108		}
109		abs, err := filepath.Abs(transcriptPath)
110		if err != nil {
111			abs = transcriptPath
112		}
113		for _, name := range List() {
114			ag, err := Get(name)
115			if err != nil {
116				continue
117			}
118			dir, err := ag.GetSessionDir(repoPath)
119			if err != nil || dir == "" {
120				continue
121			}
122			dirAbs, err := filepath.Abs(dir)
123			if err != nil {
124				dirAbs = dir
125			}
126			if pathHasDirPrefix(abs, dirAbs) {
127				return ag, true
128			}
129		}
130		return nil, false
131	}
132	
133	// pathHasDirPrefix reports whether path is contained within dir (or equals it).
134	// Adds a trailing separator before prefix-matching so /a/bc doesn't match /a/b.
135	//
136	// On Windows, comparison is case-insensitive: NTFS/ReFS treat paths as
137	// case-insensitive, and filepath.Abs preserves whatever casing the input had,
138	// so a transcript path like `C:\Users\Bob\.cursor\...` and a session dir like
139	// `c:\users\bob\.cursor\...` refer to the same location but would not match
140	// under a byte-wise comparison.
141	func pathHasDirPrefix(path, dir string) bool {
142		if runtime.GOOS == "windows" {
143			path = strings.ToLower(path)
144			dir = strings.ToLower(dir)
145		}
146		if path == dir {
147			return true
148		}
149		if !strings.HasSuffix(dir, string(filepath.Separator)) {
150			dir += string(filepath.Separator)
151		}
152		return strings.HasPrefix(path, dir)
153	}
154	
155	// Agent name constants (registry keys)
156	const (
157		AgentNameClaudeCode     types.AgentName = "claude-code"
158		AgentNameCodex          types.AgentName = "codex"
159		AgentNameCopilotCLI     types.AgentName = "copilot-cli"
160		AgentNameCursor         types.AgentName = "cursor"
161		AgentNameFactoryAIDroid types.AgentName = "factoryai-droid"
162		AgentNameGemini         types.AgentName = "gemini"
163		AgentNameOpenCode       types.AgentName = "opencode"
164		AgentNamePi             types.AgentName = "pi"
165	)
166	
167	// Agent type constants (type identifiers stored in metadata/trailers)
168	const (
169		AgentTypeClaudeCode     types.AgentType = "Claude Code"
170		AgentTypeCodex          types.AgentType = "Codex"
171		AgentTypeCopilotCLI     types.AgentType = "Copilot CLI"
172		AgentTypeCursor         types.AgentType = "Cursor"
173		AgentTypeFactoryAIDroid types.AgentType = "Factory AI Droid"
174		AgentTypeGemini         types.AgentType = "Gemini CLI"
175		AgentTypeOpenCode       types.AgentType = "OpenCode"
176		AgentTypePi             types.AgentType = "Pi"
177		AgentTypeUnknown        types.AgentType = "Unknown"
178	)
179	
180	// DefaultAgentName is the registry key for the default agent.
181	const DefaultAgentName types.AgentName = AgentNameClaudeCode
182	
183	// GetByAgentType retrieves an agent by its type identifier.
184	//
